class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int left = 0;
        int right = 0;
        for (int weight : weights) {
            left = Math.max(left, weight);
            right += weight;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canShip(weights, days, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canShip(int[] weights, int days, int capacity) {
        int usedDays = 1;
        int load = 0;
        for (int weight : weights) {
            if (load + weight > capacity) {
                usedDays++;
                load = 0;
            }
            load += weight;
        }
        return usedDays <= days;
    }
}

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int left = 0;
        int right = 0;
        for (int weight : weights) {
            left = Math.max(left, weight);
            right += weight;
        }

        int answer = right;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            int needed = daysNeeded(weights, mid);
            if (needed <= days) {
                answer = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return answer;
    }

    private int daysNeeded(int[] weights, int capacity) {
        int days = 1;
        int load = 0;
        for (int weight : weights) {
            if (load + weight > capacity) {
                days++;
                load = 0;
            }
            load += weight;
        }
        return days;
    }
}

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int heaviest = 0;
        int total = 0;
        for (int weight : weights) {
            heaviest = Math.max(heaviest, weight);
            total += weight;
        }

        int left = Math.max(heaviest, (total + days - 1) / days);
        int right = total;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canFinish(weights, days, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canFinish(int[] weights, int days, int capacity) {
        int usedDays = 1;
        int load = 0;
        for (int weight : weights) {
            if (load + weight > capacity) {
                usedDays++;
                load = 0;
                if (usedDays > days) {
                    return false;
                }
            }
            load += weight;
        }
        return true;
    }
}

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int n = weights.length;
        int[] prefix = new int[n + 1];
        int heaviest = 0;
        for (int i = 0; i < n; i++) {
            heaviest = Math.max(heaviest, weights[i]);
            prefix[i + 1] = prefix[i] + weights[i];
        }

        int left = heaviest;
        int right = prefix[n];
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canShip(prefix, days, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

    private boolean canShip(int[] prefix, int days, int capacity) {
        int index = 0;
        int n = prefix.length - 1;
        for (int day = 0; day < days && index < n; day++) {
            int limit = prefix[index] + capacity;
            index = upperBound(prefix, limit) - 1;
        }
        return index == n;
    }

    private int upperBound(int[] values, int target) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}
